function previewNote({t}){return `<div class="ops-preview-note" role="note"><span class="ops-preview-dot" aria-hidden="true"></span><strong>${t('介面預覽','Interface preview')}</strong><span>${t('以下為虛構示範資料；操作只改變預覽，不會收款、傳送訊息或連接外部服務。','Fictional sample records. Actions change this preview only; no payment, message delivery or external connection occurs.')}</span></div>`;}
