function messagesPage(state,data,ctx){const {t,esc}=ctx,query=String(state.query||'').toLowerCase(),threads=data.threads.filter(row=>!query||[label(row,'name',ctx),label(row,'subject',ctx)].join(' ').toLowerCase().includes(query)),selected=threads.find(row=>row.id===state.selectedThreadId)||threads[0];return heading('messages',t('訊息','Messages'),t('讓每個家庭的對話都有清楚脈絡。','Keep every family conversation in context.'),button('compose',t('撰寫訊息','Compose message'),'messages','',false,ctx),ctx)+`<div class="ops-body">${previewNote(ctx)}<section class="ops-inbox"><aside class="ops-conversation-list" aria-label="${t('對話列表','Conversation list')}"><div class="ops-inbox-search ops-filters">${field(t('搜尋對話','Search conversations'),input('query',state.query||'','search',`placeholder="${esc(t('家長或主旨','Parent or subject'))}"`),ctx)}${button('apply-filters',t('搜尋','Search'),'messages','',true,ctx)}</div>${threads.map(row=>`<button type="button" class="ops-thread-button${row.id===selected?.id?' is-active':''}" data-action="ui-operations" data-ui-command="thread" data-ui-section="messages" data-ui-id="${esc(row.id)}" aria-pressed="${row.id===selected?.id}"><span class="ops-avatar" aria-hidden="true">${esc(label(row,'name',ctx).slice(0,1))}</span><span class="ops-thread-copy"><strong>${esc(label(row,'name',ctx))}</strong><span>${esc(label(row,'subject',ctx))}</span><small>${esc(row.date)}</small></span>${row.unread?`<span class="ops-unread" aria-label="${t(`${row.unread} 則未讀`,`${row.unread} unread`)}">${row.unread}</span>`:''}</button>`).join('')||`<p class="ops-muted ops-inbox-empty">${t('沒有符合的對話','No matching conversations')}</p>`}</aside><section class="ops-thread-panel">${selected?`<header class="ops-thread-heading"><div><h2>${esc(label(selected,'name',ctx))}</h2><p>${esc(label(selected,'subject',ctx))}</p></div>${badge(t('虛構對話','Fictional conversation'),'preview',ctx)}</header><div class="ops-message-history" role="log" aria-label="${t('訊息紀錄','Message history')}"><p class="ops-message-date">${esc(selected.date)}</p>${selected.messages.map(row=>`<article class="ops-message-bubble ${row.from==='studio'?'is-studio':''}"><span class="ops-message-sender">${row.from==='studio'?t('畫室 · 預覽','Studio · Preview'):esc(label(selected,'name',ctx))}</span><p>${esc(label(row,'text',ctx))}</p><time>${esc(row.time)}</time></article>`).join('')}</div><div class="ops-composer">${field(t('回覆內容','Reply'),textArea('message',state.messageDraft||'',3),ctx)}<div><small>${t('只預覽訊息，不會傳送。','Preview only. Nothing will be sent.')}</small>${button('preview-reply',t('預覽回覆','Preview reply'),'messages',selected.id,false,ctx)}</div></div>`:empty(t('選擇一個對話','Choose a conversation'),t('選擇左側對話，或撰寫新訊息。','Choose a conversation or compose a new message.'),button('compose',t('撰寫訊息','Compose message'),'messages','',false,ctx),ctx)}</section></section></div>`;}
function channelsPage(state,data,ctx){const {t,esc}=ctx;return heading('channels',t('渠道','Channels'),t('統一整理家長聯絡與公開展示入口。','Organize family communication and public entry points.'),'',ctx)+`<div class="ops-body">${previewNote(ctx)}<div class="ops-channel-grid">${data.channels.map(row=>`<article class="ops-channel-card"><div class="ops-channel-card-heading"><span class="ops-channel-icon">${icon(row.kind)}</span>${badge(statusLabel(row.status,ctx),row.status,ctx)}</div><h2>${esc(label(row,'name',ctx))}</h2><p>${esc(label(row,'description',ctx))}</p><dl><div><dt>${t('顯示名稱','Display name')}</dt><dd>${esc(row.senderName)}</dd></div><div><dt>${t('連接狀態','Connection')}</dt><dd>${t('僅設定介面預覽','Settings preview only')}</dd></div></dl><footer>${button('channel-details',t('查看詳情','View details'),'channels',row.id,true,ctx)}${button('channel-settings',t('設定','Settings'),'channels',row.id,false,ctx)}</footer></article>`).join('')}</div><div class="ops-support-note"><span>${icon('channels')}</span><div><h2>${t('先安排好流程，再連接服務','Prepare the workflow before connecting services')}</h2><p>${t('這裡可檢視各渠道的設定方式。正式訊息傳送、付款服務與網上發布將在後續連接。','Review each channel’s settings here. Message delivery, payment services and online publishing will be connected in a later phase.')}</p></div></div></div>`;}
const settingsTabs = ctx => [['general',ctx.t('一般資料','General')],['courses',ctx.t('課程設定','Courses')],['notifications',ctx.t('通知設定','Notifications')],['payments',ctx.t('付款設定','Payments')],['templates',ctx.t('單據樣式','Templates')],['coupons',ctx.t('優惠券範本','Coupon templates')],['email-templates',ctx.t('預設電郵範本','Email templates')],['public-visibility',ctx.t('公開時段顯示','Public slot visibility')]];
function settingsFields(tab,settings,ctx,data){const {t}=ctx,s=settings[tab]||{};if(['coupons','email-templates','public-visibility'].includes(tab))return advancedSettingsFields(tab,data,ctx);if(tab==='courses')return `<div class="ops-form-grid">${field(t('預設課堂時長（分鐘）','Default lesson duration (minutes)'),input('duration',s.duration,'number','min="15" max="480" step="15" required'),ctx)}${field(t('預設班額','Default class capacity'),input('capacity',s.capacity,'number','min="1" max="100" required'),ctx)}${field(t('時間表間距（分鐘）','Timetable interval (minutes)'),select('interval',[[15,'15'],[30,'30'],[60,'60']],s.interval,ctx),ctx)}${field(t('可預約日數','Booking window (days)'),input('bookingDays',s.bookingDays,'number','min="1" max="365" required'),ctx)}</div>${toggle('allowWaitlist',t('顯示候補選項','Show waitlist option'),t('此選項只展示未來可使用的候補設定。','Shows the intended waitlist preference in this preview.'),s.allowWaitlist,ctx)}<div class="ops-inline-note">${t('已確認名額與出席紀錄分開處理；缺席不會自動釋放名額。','Confirmed seats and attendance are separate. Absence does not automatically release a seat.')}</div>`;if(tab==='notifications')return `${toggle('inApp',t('平台內通知','In-app notifications'),t('課堂、申請與付款狀態的提醒入口。','A home for lesson, request and payment reminders.'),s.inApp,ctx)}${toggle('email',t('電郵通知','Email notifications'),t('尚未連接電郵服務，這裡只保留偏好預覽。','Email is not connected; this is a preference preview.'),s.email,ctx)}${toggle('whatsapp',t('WhatsApp 提醒','WhatsApp reminders'),t('不會自動向家長傳送訊息。','No messages are automatically sent to families.'),s.whatsapp,ctx)}<h3>${t('提醒內容','Reminder preferences')}</h3>${toggle('payment',t('付款進度','Payment updates'),t('訂單待確認與付款待核實。','Order confirmation and payment verification.'),s.payment,ctx)}${toggle('lesson',t('課堂安排','Lesson updates'),t('課堂時間與補堂安排。','Lesson times and make-up arrangements.'),s.lesson,ctx)}${field(t('上課前提醒（小時）','Lesson reminder (hours before)'),select('reminderHours',[[0,t('不提醒','No reminder')],[12,'12'],[24,'24'],[48,'48']],s.reminderHours,ctx),ctx)}`;if(tab==='payments')return `<div class="ops-form-grid">${field(t('付款方式','Payment method'),select('method',[['fps',t('轉數快 FPS','FPS')],['bank',t('銀行轉帳','Bank transfer')],['cash',t('現金','Cash')]],s.method,ctx),ctx)}${field(t('核實方式','Verification'),`<input name="verification" value="${t('人手核實','Manual verification')}" readonly>`,ctx)}${field(t('收款戶名（預覽）','Account name (preview)'),input('accountName',s.accountName),ctx)}${field(t('付款參考資料（預覽）','Payment reference (preview)'),input('reference',s.reference,'text',`placeholder="${t('留空，尚未連接真實收款','Blank; no live payment connection')}"`),ctx)}${field(t('預設付款期限（日）','Default payment terms (days)'),input('dueDays',s.dueDays,'number','min="1" max="90"'),ctx)}${field(t('家長付款說明','Payment instructions for parents'),textArea('paymentNote',s.paymentNote),ctx,true)}</div><div class="ops-inline-note">${t('家長確認訂單後仍須等候核實付款；這個介面不會處理真實收款。','Parent confirmation still requires payment verification. This interface does not process actual payments.')}</div>`;if(tab==='templates')return `<div class="ops-form-grid">${field(t('單據抬頭','Invoice heading'),input('title',s.title,'text','required maxlength="120"'),ctx)}${field(t('單據編號前綴','Invoice number prefix'),input('prefix',s.prefix,'text','maxlength="16"'),ctx)}${field(t('頁尾文字','Footer text'),textArea('footer',s.footer),ctx,true)}</div>${toggle('showStudent',t('顯示學生名稱','Show student name'),t('於單據資料區顯示學生。','Include the student in invoice details.'),s.showStudent,ctx)}${toggle('showTeachers',t('顯示老師名稱','Show teacher names'),t('於課堂項目顯示老師。','Include teachers alongside lesson items.'),s.showTeachers,ctx)}${toggle('showPaymentInstructions',t('顯示付款說明','Show payment instructions'),t('於單據下方展示付款注意事項。','Include payment instructions below the items.'),s.showPaymentInstructions,ctx)}<div class="ops-template-sample"><strong>BEAMAL</strong><span>${t('單據預覽','Invoice preview')} · PREVIEW-INV-001</span><div><span>${t('繪畫課程','Drawing course')}</span><b>HK$1,200.00</b></div><small>${t('以上為版面示意，不是真實單據。','Layout example; not an actual invoice.')}</small>${button('view-invoice',t('查看完整樣式','View full layout'),'accounting','invoice-1',true,ctx)}</div>`;return `<div class="ops-form-grid">${field(t('畫室名稱','Studio name'),input('studioName',s.studioName,'text','required maxlength="120"'),ctx)}${field(t('簡稱','Short name'),input('shortName',s.shortName,'text','maxlength="40"'),ctx)}${field(t('聯絡電郵（預覽）','Contact email (preview)'),input('email',s.email,'email'),ctx)}${field(t('聯絡電話（預覽）','Contact phone (preview)'),input('phone',s.phone,'tel',`placeholder="${t('尚未設定','Not set')}"`),ctx)}${field(t('地址（預覽）','Address (preview)'),textArea('address',s.address,2),ctx,true)}${field(t('時區','Time zone'),select('timezone',[['Asia/Hong_Kong','Hong Kong · UTC+08:00']],s.timezone,ctx),ctx)}${field(t('預設語言','Default language'),select('language',[['zh','繁體中文'],['en','English']],s.language,ctx),ctx)}${field(t('貨幣','Currency'),select('currency',[['HKD','HKD · Hong Kong dollar']],s.currency,ctx),ctx)}</div>`;}
function settingsPage(state,data,ctx){const {t,esc}=ctx,tabs=settingsTabs(ctx),tab=tabs.some(([id])=>id===state.settingsTab)?state.settingsTab:'general',title=tabs.find(([id])=>id===tab)[1];return heading('settings',t('設定','Settings'),t('讓畫室日常運作保持一致。','Keep the studio’s everyday operations consistent.'),'',ctx)+`<div class="ops-body">${previewNote(ctx)}<div class="ops-settings-layout"><nav class="ops-settings-nav" aria-label="${t('設定分類','Settings categories')}">${tabs.map(([id,text])=>`<button type="button" data-action="ui-operations" data-ui-command="settings-tab" data-ui-section="settings" data-ui-id="${id}"${id===tab?' aria-current="page"':''}>${esc(text)}<span aria-hidden="true">›</span></button>`).join('')}</nav><section class="ops-settings-panel"><header><h2>${esc(title)}</h2><p>${t('這些設定只用於介面預覽，尚未套用至真實系統。','These settings apply to the interface preview and are not connected to the live system.')}</p></header><form id="ui-operations-settings"><input type="hidden" name="formKind" value="settings"><input type="hidden" name="formSection" value="settings"><input type="hidden" name="settingsTab" value="${tab}"><div class="ops-settings-fields">${settingsFields(tab,data.settings,ctx,data)}</div><footer class="ops-form-footer"${['coupons','email-templates'].includes(tab)?' hidden':''}><span>${t('只更新此介面預覽','Updates this interface preview only')}</span><button class="ops-primary" type="submit">${t('更新設定預覽','Update settings preview')}</button></footer></form></section></div></div>`;}
export function operationsPageMarkup(section,state={},providedContext){const ctx=context(providedContext),data=dataFor(state),renderer={products:productPage,accounting:accountingPage,messages:messagesPage,channels:channelsPage,settings:settingsPage}[section];return `<section class="ops-page" data-ops-section="${ctx.esc(section)}">${state.error&&!state.dialog?`<p class="ops-feedback ops-error-feedback" role="alert">${ctx.esc(state.error)}</p>`:''}${state.notice?`<p class="ops-feedback" role="status">${ctx.esc(state.notice)}</p>`:''}${renderer?renderer(state,data,ctx):empty(ctx.t('此頁面暫未提供','Page unavailable'),ctx.t('請從側欄選擇其他頁面。','Choose another page from the sidebar.'),'',ctx)}</section>`;}
function formShell(title,kind,section,body,ctx,id='',submitLabel){return `<div class="modal ops-modal" role="dialog" aria-modal="true" aria-labelledby="ops-dialog-title"><div class="dialog ops-dialog" tabindex="-1"><header><div><span class="ops-eyebrow">${ctx.t('介面預覽','Interface preview')}</span><h2 id="ops-dialog-title">${ctx.esc(title)}</h2></div>${button('close','×',section,'',true,ctx)}</header><form id="ui-operations-form"><input type="hidden" name="formKind" value="${ctx.esc(kind)}"><input type="hidden" name="formSection" value="${ctx.esc(section)}"><input type="hidden" name="recordId" value="${ctx.esc(id)}"><div class="ops-dialog-body">${body}<p class="ops-dialog-disclosure">${ctx.t('以下操作只更新虛構預覽，不會儲存至正式資料、收款或傳送訊息。','This action updates fictional preview data only. It does not save live records, process payments or send messages.')}</p><p class="ops-form-error" role="alert">${ctx.esc(ctx.error||'')}</p></div><footer class="ops-dialog-footer">${button('close',ctx.t('取消','Cancel'),section,'',true,ctx)}<button type="submit" class="ops-primary">${ctx.esc(submitLabel||ctx.t('更新預覽','Update preview'))}</button></footer></form></div></div>`;}
function detailShell(title,section,body,actions,ctx){return `<div class="modal ops-modal" role="dialog" aria-modal="true" aria-labelledby="ops-dialog-title"><div class="dialog ops-dialog" tabindex="-1"><header><div><span class="ops-eyebrow">${ctx.t('介面預覽','Interface preview')}</span><h2 id="ops-dialog-title">${ctx.esc(title)}</h2></div>${button('close','×',section,'',true,ctx)}</header><div class="ops-dialog-body">${body}</div><footer class="ops-dialog-footer">${button('close',ctx.t('關閉','Close'),section,'',true,ctx)}${actions||''}</footer></div></div>`;}
function productDialog(type,id,data,values,ctx){const {t,esc}=ctx,row={...(data.products.find(row=>row.id===id)||{sku:'',nameZh:'',nameEn:'',category:'materials',price:'',cost:'',stock:0,threshold:4,status:'draft',description:'',descriptionEn:''}),...values};if(type==='product'||type==='view-product')return detailShell(label(row,'name',ctx),'products',`<div class="ops-product-detail"><span class="ops-product-mark">${icon('products')}</span><div>${badge(statusLabel(row.status,ctx),row.status,ctx)}<p>${esc(row.sku)} · ${esc(categoryLabel(row.category,ctx))}</p><strong>${currency(row.price)}</strong></div></div><p>${esc(t(row.description,row.descriptionEn))}</p><dl class="ops-facts"><div><dt>${t('現有庫存','Current stock')}</dt><dd>${esc(row.stock)}</dd></div><div><dt>${t('補貨提示數量','Reorder level')}</dt><dd>${esc(row.threshold)}</dd></div><div><dt>${t('成本（樣本）','Cost (example)')}</dt><dd>${currency(row.cost)}</dd></div></dl>`,button('edit-product',t('編輯產品','Edit product'),'products',row.id,false,ctx)+button('stock-product',t('調整庫存','Adjust stock'),'products',row.id,true,ctx),ctx);if(type==='stock-product')return formShell(t('調整庫存預覽','Adjust stock preview'),'stock-product','products',`<div class="ops-inline-note"><strong>${esc(label(row,'name',ctx))}</strong><span>${t('現有庫存：','Current stock: ')}${esc(row.stock)}</span></div><div class="ops-form-grid">${field(t('調整方式','Adjustment'),select('direction',[['add',t('入貨／增加','Receive / increase')],['remove',t('領用／減少','Use / decrease')]],values.direction||'add',ctx),ctx)}${field(t('數量','Quantity'),input('quantity',values.quantity||1,'number','min="1" step="1" required'),ctx)}${field(t('原因','Reason'),textArea('reason',values.reason||'',3),ctx,true)}</div>`,ctx,row.id,t('預覽庫存調整','Preview stock adjustment'));return formShell(type==='edit-product'?t('編輯產品','Edit product'):t('新增產品','Create product'),type==='edit-product'?'edit-product':'create-product','products',`<div class="ops-form-grid">${field(t('產品中文名稱','Product name (Chinese)'),input('nameZh',row.nameZh,'text','required maxlength="120"'),ctx)}${field(t('產品英文名稱','Product name (English)'),input('nameEn',row.nameEn,'text','required maxlength="120"'),ctx)}${field(t('產品編號','SKU'),input('sku',row.sku,'text','required maxlength="40"'),ctx)}${field(t('分類','Category'),select('category',['materials','kits','accessories'].map(key=>[key,categoryLabel(key,ctx)]),row.category,ctx),ctx)}${field(t('售價（港元）','Selling price (HKD)'),input('price',row.price,'number','min="0" step="0.01" required'),ctx)}${field(t('成本（港元，預覽）','Cost (HKD, preview)'),input('cost',row.cost,'number','min="0" step="0.01"'),ctx)}${field(t('現有庫存','Current stock'),input('stock',row.stock,'number','min="0" step="1" required'),ctx)}${field(t('補貨提示數量','Reorder level'),input('threshold',row.threshold,'number','min="0" step="1" required'),ctx)}${field(t('狀態','Status'),select('status',['draft','active','archived'].map(key=>[key,statusLabel(key,ctx)]),row.status,ctx),ctx)}${field(t('中文說明','Description (Chinese)'),textArea('description',row.description,3),ctx,true)}${field(t('英文說明','Description (English)'),textArea('descriptionEn',row.descriptionEn,3),ctx,true)}</div>`,ctx,row.id,t('更新產品預覽','Update product preview'));}
function invoiceDialog(type,id,data,values,ctx){const {t,esc}=ctx,row=data.invoices.find(row=>row.id===id)||data.invoices[0],student=id=>label(data.students.find(row=>row.id===id),'name',ctx);if(type==='invoice'||type==='view-invoice'){const subtotal=row.items.reduce((sum,item)=>sum+item.quantity*item.unitPrice,0),total=invoiceTotal(row);return detailShell(row.number,'accounting',`<article class="ops-invoice-sheet"><div class="ops-invoice-brand"><strong>Beamal Art Studio</strong><span>${row.orderPreviewSource?t('訂單文件版面預覽 · 尚未生成 PDF','Order document layout preview · PDF not generated'):t('虛構單據 · 非付款要求','Fictional invoice · Not a payment request')}</span></div><div class="ops-invoice-meta"><div><span>${t('學生','Student')}</span><strong>${esc(student(row.studentId))}</strong></div><div><span>${t('單據日期','Issue date')}</span><strong>${esc(row.date)}</strong></div><div><span>${t('到期日期','Due date')}</span><strong>${esc(row.dueDate)}</strong></div><div><span>${t('狀態','Status')}</span>${badge(statusLabel(row.status,ctx),row.status,ctx)}</div></div>${table([t('項目','Item'),t('數量','Quantity'),t('單價','Unit price'),t('小計','Line total')],row.items.map(item=>`<tr><td>${esc(label(item,'name',ctx))}</td><td>${esc(item.quantity)}</td><td>${currency(item.unitPrice)}</td><td class="ops-money">${currency(item.quantity*item.unitPrice)}</td></tr>`).join(''),t('單據項目','Invoice items'),ctx)}<dl class="ops-invoice-totals"><div><dt>${t('小計','Subtotal')}</dt><dd>${currency(subtotal)}</dd></div><div><dt>${t('折扣','Discount')}</dt><dd>− ${currency(row.discount)}</dd></div><div class="ops-invoice-total"><dt>${t('合計','Total')}</dt><dd>${currency(total)}</dd></div><div><dt>${t('待付金額','Balance due')}</dt><dd>${currency(row.status==='paid'?0:total)}</dd></div></dl><p>${esc(label(row,'notes',ctx))}</p></article>`,button('receipt-options','PDF Receipt','accounting',row.id,true,ctx),ctx);}return formShell(t('新增單據預覽','Create invoice preview'),'create-invoice','accounting',`<div class="ops-form-grid">${field(t('學生','Student'),select('studentId',data.students.map(row=>[row.id,label(row,'name',ctx)]),values.studentId||data.students[0]?.id,ctx),ctx)}${field(t('單據日期','Issue date'),input('date',values.date||'2026-10-15','date','required'),ctx)}${field(t('到期日期','Due date'),input('dueDate',values.dueDate||'2026-10-22','date','required'),ctx)}${field(t('參考編號','Reference'),input('reference',values.reference||'','text',`placeholder="PREVIEW-INV"`),ctx)}</div><h3>${t('收費項目','Line items')}</h3><div class="ops-invoice-edit-items">${[1,2].map(index=>`<div class="ops-invoice-edit-row">${field(t('項目名稱','Item name'),input('itemName'+index,values['itemName'+index]||(index===1?t('繪畫課程','Drawing course'):''),'text',index===1?'required':''),ctx)}${field(t('數量','Quantity'),input('quantity'+index,values['quantity'+index]||(index===1?4:1),'number','min="1" step="1"'),ctx)}${field(t('單價（港元）','Unit price (HKD)'),input('unitPrice'+index,values['unitPrice'+index]||(index===1?300:''),'number','min="0" step="0.01"'),ctx)}</div>`).join('')}</div><div class="ops-form-grid">${field(t('折扣金額（港元）','Discount amount (HKD)'),input('discount',values.discount||0,'number','min="0" step="0.01"'),ctx)}${field(t('備註','Notes'),textArea('notes',values.notes||'',3),ctx,true)}</div>`,ctx,'',t('建立單據預覽','Create invoice preview'));}
