 const checked=name=>fields[name]===true||fields[name]==='on'||fields[name]==='true';
 const validDate=value=>typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value)&&Number.isFinite(Date.parse(value+'T12:00:00Z'));
 const newId=(prefix,rows)=>{let suffix=rows.length+1;while(rows.some(row=>row.id===`${prefix}-${suffix}`))suffix++;return `${prefix}-${suffix}`;};
 const openTypes={'view-product':'product','create-product':'create-product','edit-product':'edit-product','stock-product':'stock-product','view-invoice':'invoice','create-invoice':'create-invoice','view-payment':'payment','record-payment':'record-payment','view-credit':'credit','create-credit':'create-credit',compose:'compose','channel-details':'channel-details','channel-settings':'channel-settings','preview-invoice':'receipt-options','receipt-options':'receipt-options','receipt-email':'receipt-email','receipt-save':'receipt-save','edit-coupon':'edit-coupon','create-coupon':'create-coupon','edit-email-template':'edit-email-template'};
 if(command==='close'){next.dialog=null;next.draft={};return next;}
