 if(command==='preview-reply'||command==='preview-message'){const message=String(fields.message||state.messageDraft||'').trim();if(!message)return error('請先輸入訊息內容。','Enter a message first.');const thread=data.threads.find(row=>row.id===id),recipient=fields.recipient||thread?.[next.lang==='en'?'nameEn':'nameZh']||'';next.dialog={type:'message-preview',id,values:{...fields,message,recipient}};next.messageDraft=message;return next;}
 if(openTypes[command]&&!fields.formKind){const previous=next.dialog?.values||next.draft||{};next.dialog={type:openTypes[command],id,values:['compose','receipt-email','receipt-save'].includes(command)?previous:{}};next.draft={};return next;}
 const kind=fields.formKind||(['submit','save','form-submit'].includes(command)?next.dialog?.type:command);
 const advanced=advanceAdvancedOperations(next,command,kind,fields,{id,section,text,error,complete,number,checked,validDate,newId});if(advanced)return advanced;
 if(kind==='create-product'||kind==='edit-product'){
  const nameZh=String(fields.nameZh||'').trim(),nameEn=String(fields.nameEn||'').trim(),sku=String(fields.sku||'').trim(),price=number('price',NaN),cost=number('cost'),stock=number('stock'),threshold=number('threshold');
  if(!nameZh||!nameEn||!sku||![price,cost,stock,threshold].every(Number.isFinite)||price<0||cost<0||stock<0||threshold<0||!Number.isInteger(stock)||!Number.isInteger(threshold))return error('請填寫中英文名稱、編號及有效價格與庫存。','Enter both names, SKU and valid prices and stock.');
  if(data.products.some(row=>row.id!==id&&row.sku.toLowerCase()===sku.toLowerCase()))return error('產品編號已在預覽中使用。','This SKU is already used in the preview.');
  const current=data.products.find(row=>row.id===id);if(kind==='edit-product'&&!current)return error('找不到這個產品預覽。','This product preview is unavailable.');const record={...current,id:current?.id||newId('product',data.products),nameZh,nameEn,sku,category:['materials','kits','accessories'].includes(fields.category)?fields.category:'materials',price,cost,stock,threshold,status:['active','draft','archived'].includes(fields.status)?fields.status:'draft',description:String(fields.description||''),descriptionEn:String(fields.descriptionEn||'')};data.products=data.products.filter(row=>row.id!==record.id).concat(record);next.dialog={type:'product',id:record.id};return complete('產品預覽已更新；未儲存至正式資料。','Product preview updated; no live record was saved.');
 }
 if(kind==='stock-product'){const record=data.products.find(row=>row.id===id),quantity=number('quantity',NaN);if(!record||!Number.isInteger(quantity)||quantity<1)return error('請輸入有效的正整數數量。','Enter a valid positive whole quantity.');if(fields.direction==='remove'&&quantity>record.stock)return error('減少數量不可超過現有預覽庫存。','The decrease cannot exceed the preview stock.');record.stock+=fields.direction==='remove'?-quantity:quantity;next.dialog={type:'product',id};return complete('庫存預覽已更新。','Stock preview updated.');}
 if(kind==='create-invoice'){
  const items=[1,2].map(index=>({nameZh:String(fields['itemName'+index]||'').trim(),nameEn:String(fields['itemName'+index]||'').trim(),quantity:number('quantity'+index,1),unitPrice:number('unitPrice'+index)})).filter(row=>row.nameEn),discount=number('discount');
  if(!data.students.some(row=>row.id===fields.studentId)||!validDate(fields.date)||!validDate(fields.dueDate)||fields.dueDate<fields.date||!items.length||items.some(row=>!Number.isInteger(row.quantity)||row.quantity<1||!Number.isFinite(row.unitPrice)||row.unitPrice<0)||!Number.isFinite(discount)||discount<0||discount>items.reduce((sum,row)=>sum+row.quantity*row.unitPrice,0))return error('請核對學生、日期、項目金額及折扣。','Check the student, dates, item amounts and discount.');
  const record={id:newId('invoice',data.invoices),number:'PREVIEW-INV-'+String(data.invoices.length+1).padStart(3,'0'),studentId:fields.studentId,date:fields.date,dueDate:fields.dueDate,status:'draft',items,discount,notesZh:String(fields.notes||''),notesEn:String(fields.notes||'')};data.invoices.push(record);next.dialog={type:'invoice',id:record.id};return complete('虛構單據預覽已建立；沒有付款要求。','Fictional invoice preview created; no payment was requested.');
 }
 if(kind==='record-payment'){const invoice=data.invoices.find(row=>row.id===fields.invoiceId),amount=number('amount',NaN);if(!invoice||!Number.isFinite(amount)||amount<=0||!validDate(fields.date))return error('請選擇單據並輸入有效金額與日期。','Select an invoice and enter a valid amount and date.');const record={id:newId('payment',data.payments),reference:String(fields.reference||'PREVIEW-PAY-'+String(data.payments.length+1).padStart(3,'0')),invoiceId:invoice.id,studentId:invoice.studentId,date:fields.date,amount,method:['fps','cash','bank'].includes(fields.method)?fields.method:'fps',status:'preview',note:String(fields.note||'')};data.payments.push(record);next.dialog={type:'payment',id:record.id};return complete('已加入虛構收款預覽；未處理付款或更改正式單據。','Fictional payment preview added; no payment was processed or live invoice changed.');}
 if(kind==='create-credit'){const amount=number('amount',NaN);if(!data.students.some(row=>row.id===fields.studentId)||!Number.isFinite(amount)||amount<=0||!validDate(fields.date)||!String(fields.reason||'').trim())return error('請填寫學生、有效金額、日期與原因。','Enter a student, valid amount, date and reason.');const record={id:newId('credit',data.credits),number:'PREVIEW-CR-'+String(data.credits.length+1).padStart(3,'0'),studentId:fields.studentId,invoiceId:fields.invoiceId,date:fields.date,amount,status:'available',reasonZh:fields.reason,reasonEn:fields.reason};data.credits.push(record);next.dialog={type:'credit',id:record.id};return complete('調整預覽已建立；沒有退款或帳戶餘額變動。','Credit preview created; no refund or account balance changed.');}
 if(kind==='compose'){const subject=String(fields.subject||'').trim(),message=String(fields.message||'').trim();if(!subject||!message||!fields.recipient)return error('請選擇收件人並填寫主旨及訊息。','Choose a recipient and enter a subject and message.');next.dialog={type:'message-preview',values:{recipient:fields.recipient,subject,message}};return next;}
 if(kind==='channel-settings'){const channel=data.channels.find(row=>row.id===id);if(!channel||!String(fields.senderName||'').trim())return error('請填寫顯示名稱。','Enter a display name.');Object.assign(channel,{senderName:String(fields.senderName).trim(),replyEmail:String(fields.replyEmail||''),contactReference:String(fields.contactReference||''),descriptionZh:String(fields.description||channel.descriptionZh),descriptionEn:String(fields.description||channel.descriptionEn),enabled:checked('enabled')});next.dialog={type:'channel-details',id};return complete('渠道設定預覽已更新；未連接外部服務。','Channel settings preview updated; no external service was connected.');}
 if(kind==='settings'){const tab=fields.settingsTab||next.settingsTab||'general',current=data.settings[tab];if(!current)return error('請選擇有效設定分類。','Choose a valid settings category.');const record={...current};for(const [key,value] of Object.entries(current)){if(typeof value==='boolean')record[key]=checked(key);else if(typeof value==='number'){const parsed=number(key,value);if(!Number.isFinite(parsed)||parsed<0)return error('請核對設定數值。','Check the setting values.');record[key]=parsed;}else if(fields[key]!==undefined)record[key]=String(fields[key]);}if(tab==='public-visibility'&&(!Number.isInteger(record.publicDays)||record.publicDays<7||record.publicDays>30))return error('公開展示日數必須為 7 至 30 日。','Public availability must be 7–30 days.');if(tab==='general'&&!String(record.studioName||'').trim())return error('請填寫畫室名稱。','Enter the studio name.');if(tab==='payments')record.verification='manual';data.settings[tab]=record;next.dialog=null;return complete('設定預覽已更新；尚未套用至正式系統。','Settings preview updated; not applied to the live system.');}
