function advancedSettingsFields(tab,data,ctx){const {t,esc}=ctx;if(tab==='coupons')return `<div class="ops-setting-list-heading"><p>${t('建立與檢視優惠券樣式；不會套用至真實訂單。','Create and review coupon examples; no real order is discounted.')}</p>${button('create-coupon',t('新增優惠券範本','Create coupon template'),'settings','',false,ctx)}</div><div class="ops-setting-list">${data.coupons.map(row=>`<article><div><h3>${esc(label(row,'name',ctx))}</h3><p><code>${esc(row.code)}</code> · ${row.discountType==='percent'?esc(row.value)+'%':currency(row.value)}</p><small>${t('到期日：','Expires: ')}${esc(row.expiryDate||'—')} · ${t('使用次數樣本：','Example uses: ')}${row.uses} / ${row.maxUses}</small></div><div>${badge(row.active?t('啟用樣本','Active example'):t('停用樣本','Inactive example'),row.active?'active':'draft',ctx)}${button('edit-coupon',t('編輯','Edit'),'settings',row.id,true,ctx)}</div></article>`).join('')}</div>`;if(tab==='email-templates')return `<p class="ops-muted">${t('管理通知內容範本。所有電郵仍為預覽，不會自動寄出。','Manage notification copy. All emails remain previews and are not delivered automatically.')}</p><div class="ops-setting-list">${data.emailTemplates.map(row=>`<article><div><h3>${esc(label(row,'name',ctx))}</h3><p>${esc(label(row,'subject',ctx))}</p><small>${t('支援學生、課程、日期等預覽變數','Supports student, course and date preview variables')}</small></div>${button('edit-email-template',t('編輯範本','Edit template'),'settings',row.id,true,ctx)}</article>`).join('')}</div>`;const settings=data.settings['public-visibility'];return `<div class="ops-form-grid">${field(t('公開展示範圍（日）','Public availability window (days)'),input('publicDays',settings.publicDays,'number','min="7" max="30" step="1" required'),ctx)}</div><p class="ops-muted">${t('可選 7 至 30 日。此設定只預覽公開時段的顯示方式。','Choose 7–30 days. This previews how public availability will be displayed.')}</p>${toggle('showFullTrialSlots',t('顯示已滿試堂時段','Show full trial slots'),t('讓家長看見滿額狀態的版面樣式。','Preview how full trial availability is presented.'),settings.showFullTrialSlots,ctx)}${toggle('showReschedulingSlots',t('顯示可補堂／轉堂時段','Show rescheduling slots'),t('只展示顯示偏好，未變更任何資格或名額。','Display preference only; no eligibility or capacity changes.'),settings.showReschedulingSlots,ctx)}${toggle('showTeacherNames',t('顯示老師名稱','Show teacher names'),t('只顯示公開排課資料，不展示學生身份。','Show public scheduling details without student identities.'),settings.showTeacherNames,ctx)}<div class="ops-inline-note">${t('公開頁面不應展示學生姓名、聯絡資料或內部備註。','Public pages do not show student names, contacts or internal notes.')}</div>`;}
function receiptDocument(id,data){const payment=data.payments.find(row=>row.id===id),invoice=data.invoices.find(row=>row.id===(payment?.invoiceId||id))||data.invoices[0];return {invoice,payment,filename:`${invoice.number}-receipt-preview.pdf`};}
function receiptDialog(type,id,data,values,ctx){const {t,esc}=ctx,{invoice,filename}=receiptDocument(id,data);if(type==='receipt-options')return detailShell('PDF Receipt','accounting',`<div class="ops-receipt-intro"><span class="ops-channel-icon">${icon('accounting')}</span><div><h3>${esc(invoice.number)}</h3><p>${t('選擇單據的儲存或電郵版面。','Choose the receipt saving or email layout.')}</p></div></div><div class="ops-receipt-choices"><div><h3>${t('儲存','Save')}</h3><p>${t('檢視檔名與文件設定。尚未生成 PDF。','Review the file name and document settings. No PDF has been generated.')}</p>${button('receipt-save',t('儲存','Save'),'accounting',id,false,ctx)}</div><div><h3>${t('以電郵傳送','Send by Email')}</h3><p>${t('準備收件人、範本與附件名稱；只預覽，不寄出。','Prepare the recipient, template and attachment name. Preview only; nothing is sent.')}</p>${button('receipt-email',t('以電郵傳送','Send by Email'),'accounting',id,true,ctx)}</div></div><p class="ops-inline-note">${t('這是文件功能介面預覽；付款狀態沿用虛構單據樣本，不會更改。','Document interface preview. The fictional invoice’s payment state remains unchanged.')}</p>`,'',ctx);if(type==='receipt-save-preview')return detailShell(t('儲存設定預覽','Save settings preview'),'accounting',`<div class="ops-inline-note"><strong>${esc(values.filename||filename)}</strong><span>${t('PDF 尚未生成，沒有建立或下載檔案。','The PDF has not been generated. No file was created or downloaded.')}</span></div><dl class="ops-facts"><div><dt>${t('紙張','Paper')}</dt><dd>${esc(values.paperSize||'A4')}</dd></div><div><dt>${t('單據','Invoice')}</dt><dd>${esc(invoice.number)}</dd></div></dl>`,button('receipt-options',t('返回單據選項','Back to receipt options'),'accounting',id,true,ctx),ctx);if(type==='receipt-email-preview')return detailShell(t('單據電郵預覽','Receipt email preview'),'accounting',`<dl class="ops-facts"><div><dt>${t('收件人','To')}</dt><dd>${esc(values.recipientEmail)}</dd></div><div><dt>${t('主旨','Subject')}</dt><dd>${esc(values.subject)}</dd></div></dl><div class="ops-message-preview-content">${esc(values.body)}</div><div class="ops-preview-attachment">${icon('accounting')}<span>${esc(values.attachmentName||filename)}<small>${t('只有附件名稱預覽，未生成檔案','Attachment name preview only; no file generated')}</small></span></div><p class="ops-inline-note">${t('電郵沒有寄出；PDF 尚未生成。','The email has not been sent. The PDF has not been generated.')}</p>`,button('receipt-email',t('返回編輯','Back to edit'),'accounting',id,true,ctx),ctx);if(type==='receipt-save')return formShell(t('儲存單據設定預覽','Save receipt settings preview'),'receipt-save','accounting',`<div class="ops-form-grid">${field(t('檔案名稱','File name'),input('filename',values.filename||filename,'text','required maxlength="160"'),ctx,true)}${field(t('紙張大小','Paper size'),select('paperSize',[['A4','A4'],['Letter','Letter']],values.paperSize||'A4',ctx),ctx)}${field(t('文件語言','Document language'),select('documentLanguage',[['zh','繁體中文'],['en','English']],values.documentLanguage||t('zh','en'),ctx),ctx)}</div><p class="ops-inline-note">${t('只預覽設定。尚未生成或下載 PDF。','Settings preview only. The PDF has not been generated or downloaded.')}</p>`,ctx,id,t('預覽儲存設定','Preview Save settings'));const template=data.emailTemplates.find(row=>row.id===(values.templateId||'email-template-4'))||data.emailTemplates[0],defaultSubject=label(template,'subject',ctx).replaceAll('{{invoice_number}}',invoice.number),defaultBody=label(template,'body',ctx).replaceAll('{{attachment_name}}',filename);return formShell(t('單據電郵設定預覽','Receipt email settings preview'),'receipt-email','accounting',`<div class="ops-form-grid">${field(t('收件人電郵','Recipient email'),input('recipientEmail',values.recipientEmail||'family@example.test','email','required'),ctx)}${field(t('電郵範本','Email template'),select('templateId',data.emailTemplates.map(row=>[row.id,label(row,'name',ctx)]),values.templateId||template.id,ctx),ctx)}<div class="ops-field-wide">${button('apply-email-template',t('套用至預覽','Apply to preview'),'accounting',id,true,ctx)}</div>${field(t('主旨','Subject'),input('subject',values.subject||defaultSubject,'text','required maxlength="200"'),ctx,true)}${field(t('內容','Body'),textArea('body',values.body||defaultBody,7),ctx,true)}${field(t('附件檔案名稱（預覽）','Attachment file name (preview)'),input('attachmentName',values.attachmentName||filename,'text','required maxlength="160"'),ctx,true)}</div><p class="ops-inline-note">${t('PDF 尚未生成，電郵不會寄出；此處只展示檔案名稱與電郵內容。','The PDF has not been generated and the email will not be sent. This displays the attachment name and email content only.')}</p>`,ctx,id,t('預覽電郵','Preview email'));}
function couponDialog(type,id,data,values,ctx){const {t}=ctx,row={...(data.coupons.find(row=>row.id===id)||{nameZh:'',nameEn:'',code:'',discountType:'percent',value:10,expiryDate:'2026-12-31',maxUses:20,active:true,courseScope:'all',courseName:''}),...values};return formShell(type==='create-coupon'?t('新增優惠券範本','Create coupon template'):t('編輯優惠券範本','Edit coupon template'),type,'settings',`<div class="ops-form-grid">${field(t('中文名稱','Name (Chinese)'),input('nameZh',row.nameZh,'text','required maxlength="100"'),ctx)}${field(t('英文名稱','Name (English)'),input('nameEn',row.nameEn,'text','required maxlength="100"'),ctx)}${field(t('優惠碼','Coupon code'),input('code',row.code,'text','required maxlength="24" pattern="[A-Za-z0-9_-]+"'),ctx)}${field(t('優惠類型','Discount type'),select('discountType',[['percent',t('百分比','Percentage')],['fixed',t('固定金額（港元）','Fixed amount (HKD)')]],row.discountType,ctx),ctx)}${field(t('優惠數值','Discount value'),input('value',row.value,'number','min="0.01" step="0.01" required'),ctx)}${field(t('使用上限','Maximum uses'),input('maxUses',row.maxUses,'number','min="1" step="1" required'),ctx)}${field(t('到期日期','Expiry date'),input('expiryDate',row.expiryDate,'date','required'),ctx)}${field(t('適用範圍','Applies to'),select('courseScope',[['all',t('所有課程（預覽）','All courses (preview)')],['custom',t('指定項目（預覽）','Specified item (preview)')]],row.courseScope,ctx),ctx)}${field(t('指定項目名稱（如適用）','Specified item name (if applicable)'),input('courseName',row.courseName),ctx,true)}</div>${toggle('active',t('啟用優惠券範本','Enable coupon template'),t('只展示啟用狀態，不會套用至真實訂單。','Displays the enabled state only; no live order is discounted.'),row.active,ctx)}`,ctx,id,t('更新優惠券預覽','Update coupon preview'));}
function emailTemplateDialog(id,data,values,ctx){const {t}=ctx,row={...(data.emailTemplates.find(row=>row.id===id)||data.emailTemplates[0]),...values};return formShell(t('編輯預設電郵範本','Edit preset email template'),'edit-email-template','settings',`<div class="ops-form-grid">${field(t('中文範本名稱','Template name (Chinese)'),input('nameZh',row.nameZh,'text','required maxlength="100"'),ctx)}${field(t('英文範本名稱','Template name (English)'),input('nameEn',row.nameEn,'text','required maxlength="100"'),ctx)}${field(t('中文主旨','Subject (Chinese)'),input('subjectZh',row.subjectZh,'text','required maxlength="200"'),ctx,true)}${field(t('英文主旨','Subject (English)'),input('subjectEn',row.subjectEn,'text','required maxlength="200"'),ctx,true)}${field(t('中文內容','Body (Chinese)'),textArea('bodyZh',row.bodyZh,5),ctx,true)}${field(t('英文內容','Body (English)'),textArea('bodyEn',row.bodyEn,5),ctx,true)}</div><div class="ops-template-variables"><span>{{student_name}}</span><span>{{course_name}}</span><span>{{date}}</span><span>{{amount}}</span></div><p class="ops-muted">${t('以上變數只用於範本預覽；未連接自動寄送。','These variables are for template preview; automated delivery is not connected.')}</p>`,ctx,id,t('更新範本預覽','Update template preview'));}
function advanceAdvancedOperations(next,command,kind,fields,helpers){const {id,text,error,complete,number,checked,validDate,newId}=helpers,data=next.data;
 if(command==='apply-email-template'){const template=data.emailTemplates.find(row=>row.id===fields.templateId);if(!template)return error('請選擇電郵範本。','Choose an email template.');const {invoice,filename}=receiptDocument(id,data),language=next.lang==='en'?'En':'Zh',replace=value=>String(value).replaceAll('{{invoice_number}}',invoice.number).replaceAll('{{attachment_name}}',fields.attachmentName||filename).replaceAll('{{student_name}}',data.students.find(row=>row.id===invoice.studentId)?.['name'+language]||'').replaceAll('{{amount}}',currency(invoiceTotal(invoice)));next.dialog={type:'receipt-email',id,values:{...fields,subject:replace(template['subject'+language]),body:replace(template['body'+language]),attachmentName:fields.attachmentName||filename}};return next;}
 if(kind==='receipt-save'){const filename=String(fields.filename||'').trim();if(!filename||filename.length>160||/[\/\\]/.test(filename)||!filename.toLowerCase().endsWith('.pdf'))return error('請填寫以 .pdf 結尾的檔案名稱，不要包括資料夾路徑。','Enter a file name ending in .pdf without a folder path.');next.dialog={type:'receipt-save-preview',id,values:{filename,paperSize:fields.paperSize||'A4',documentLanguage:fields.documentLanguage||'zh'}};return complete('已準備儲存設定預覽；沒有生成或下載檔案。','Save settings preview prepared; no file was generated or downloaded.');}
 if(kind==='receipt-email'){const recipientEmail=String(fields.recipientEmail||'').trim(),subject=String(fields.subject||'').trim(),body=String(fields.body||'').trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipientEmail)||!subject||!body)return error('請核對收件人電郵、主旨及內容。','Check the recipient email, subject and body.');next.dialog={type:'receipt-email-preview',id,values:{...fields,recipientEmail,subject,body}};return complete('單據電郵預覽已準備；沒有寄出電郵或生成 PDF。','Receipt email preview prepared; no email was sent and no PDF was generated.');}
 if(kind==='create-coupon'||kind==='edit-coupon'){const code=String(fields.code||'').trim().toUpperCase(),value=number('value',NaN),maxUses=number('maxUses',NaN),nameZh=String(fields.nameZh||'').trim(),nameEn=String(fields.nameEn||'').trim();if(!nameZh||!nameEn||!/^[A-Z0-9_-]{1,24}$/.test(code)||!Number.isFinite(value)||value<=0||fields.discountType==='percent'&&value>100||!Number.isInteger(maxUses)||maxUses<1||!validDate(fields.expiryDate))return error('請核對優惠券名稱、代碼、數值、日期與使用上限。','Check coupon names, code, value, expiry date and use limit.');if(data.coupons.some(row=>row.id!==id&&row.code===code))return error('這個優惠碼已在預覽中使用。','This coupon code is already used in the preview.');const current=data.coupons.find(row=>row.id===id);if(kind==='edit-coupon'&&!current)return error('找不到這個優惠券範本。','This coupon template is unavailable.');const record={...current,id:current?.id||newId('coupon',data.coupons),nameZh,nameEn,code,discountType:fields.discountType==='fixed'?'fixed':'percent',value,maxUses,expiryDate:fields.expiryDate,uses:current?.uses||0,active:checked('active'),courseScope:fields.courseScope==='custom'?'custom':'all',courseName:String(fields.courseName||'')};data.coupons=data.coupons.filter(row=>row.id!==record.id).concat(record);next.dialog=null;next.settingsTab='coupons';return complete('優惠券範本預覽已更新；未套用至真實訂單。','Coupon template preview updated; no live order was discounted.');}
 if(kind==='edit-email-template'){const current=data.emailTemplates.find(row=>row.id===id),keys=['nameZh','nameEn','subjectZh','subjectEn','bodyZh','bodyEn'];if(!current||keys.some(key=>!String(fields[key]||'').trim()))return error('請填寫中英文名稱、主旨與內容。','Enter both template names, subjects and message bodies.');for(const key of keys)current[key]=String(fields[key]).trim();next.dialog=null;next.settingsTab='email-templates';return complete('電郵範本預覽已更新；沒有寄出訊息。','Email template preview updated; no message was sent.');}
 return null;
}
